        res["secret+selfplan"]["afc_given_plan_not_identified"] = float(d["afc"][~pid].mean())
    tests = {}
    for a, b in [("secret", "secret+plan"), ("secret", "secret+irr"), ("secret+irr", "secret+plan"), ("secret", "decoy"),
