sys.path.insert(0, os.path.dirname(__file__))
from common import *
import numpy as np
from scipy.stats import spearmanr
from sklearn.linear_model import LogisticRegression
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import warnings
warnings.filterwarnings("ignore")

ACT = os.path.join(ROOT, "data", "acts"); D = os.path.join(RESULTS, "exp1")
FIG = os.path.join(ROOT, "paper_draft", "figures"); os.makedirs(FIG, exist_ok=True)
LAYERS = list(range(0, 49, 4)); LSUB = [8, 16, 24, 32, 40, 48]
S = {}


def load(name, kind="mean"):
    return np.load(os.path.join(ACT, f"{name}_{kind}.npy")).astype(np.float32)


def meta(cond):
    rows = load_jsonl(os.path.join(D, cond + ".jsonl"))
    wi = np.array([r["wi"] if "wi" in r else (r["pi"] + r["j"]) % 15 for r in rows])
    return np.array([r["pi"] for r in rows]), wi


def fit(Xtr, ytr):
    mu, sd = Xtr.mean(0), Xtr.std(0) + 1e-6
    clf = LogisticRegression(C=0.01, max_iter=300).fit((Xtr - mu) / sd, ytr)
    return lambda X: clf.predict_log_proba((X - mu) / sd)


def cv_decode(X, y, pi, Xtest=None):
    """leave-2-premises-out CV. Returns log-prob matrix [n, 15] for held-out stories (probe applied to Xtest if given)."""
    Xt = X if Xtest is None else Xtest
    out = np.zeros((len(y), 15))
    for f in range(6):
        te = (pi % 6) == f
        out[te] = fit(X[~te], y[~te])(Xt[te])
    return out


CONDS = ["secret", "secret+irr", "secret+plan", "decoy", "hide"]
ACTS = {}
for c in CONDS + ["none", "none+plan"]:
    n = c.replace("+", "_")
    if os.path.exists(os.path.join(ACT, n + "_A_mean.npy")):
        ACTS[c] = (load(n + "_A"), load(n + "_B"))
META = {c: meta(c) for c in ACTS}

# ---------------------------------------------------------------- 1. decoding by layer
dec = {}
LP = {}
for c in ACTS:
    A, B = ACTS[c]; pi, wi = META[c]
    dec[c] = {"A": [], "B": [], "delta": []}
    for l in LAYERS:
        for name, X in [("A", A[:, l]), ("B", B[:, l]), ("delta", A[:, l] - B[:, l])]:
            lp = cv_decode(X, wi, pi)
            dec[c][name].append(float((lp.argmax(1) == wi).mean()))
            LP[(c, name, l)] = lp
    print(c, {k: np.round(v, 2).tolist() for k, v in dec[c].items()}, flush=True)
S["decode_by_layer"] = dict(layers=LAYERS, acc=dec)

fig, ax = plt.subplots(1, 3, figsize=(12, 3.3), sharey=True)
for k, (name, title) in enumerate([("A", "(a) secret in prompt + own story"), ("B", "(b) same story text, no secret in prompt"),
                                   ("delta", "(c) difference (a) - (b)")]):
    for c in ACTS:
        if name == "B" and c.startswith("none"):
            continue
        ax[k].plot(LAYERS, dec[c][name], marker="o", ms=3, label=c.replace("none", "control story"))
    ax[k].axhline(1 / 15, color="k", ls="--", lw=1); ax[k].set_title(title, fontsize=9); ax[k].set_xlabel("layer")
ax[0].set_ylabel("15-way probe accuracy\n(held-out premises)"); ax[2].legend(fontsize=7)
plt.tight_layout(); plt.savefig(os.path.join(FIG, "decode_by_layer.pdf")); plt.close()

# ---------------------------------------------------------------- 2. decoding by position in the story
pos = {}
for c in ["secret", "secret+plan"]:
    if c not in ACTS:
        continue
    n = c.replace("+", "_")
    QA, QB = load(n + "_A", "quart"), load(n + "_B", "quart"); pi, wi = META[c]
    pos[c] = {}
    for li, l in enumerate(LSUB):
        if l not in (16, 24, 32):
            continue
        pos[c][l] = {"A": [], "B": [], "delta": []}
        for q in range(4):
            for name, X in [("A", QA[:, li, q]), ("B", QB[:, li, q]), ("delta", QA[:, li, q] - QB[:, li, q])]:
                lp = cv_decode(X, wi, pi)
                pos[c][l][name].append(float((lp.argmax(1) == wi).mean()))
    print("position", c, pos[c], flush=True)
S["decode_by_position"] = pos

# ---------------------------------------------------------------- 3. representation strength vs. leakage
# strength = held-out probe margin for the true word: log p(true) - mean log p(other)
def margin(lp, wi):
    t = lp[np.arange(len(wi)), wi]
    return t - (lp.sum(1) - t) / 14


def partial_spearman(x, y, groups):
    x = np.array(x, float).copy(); y = np.array(y, float).copy()
    for g_ in np.unique(groups):
        m = groups == g_
        x[m] -= x[m].mean(); y[m] -= y[m].mean()
    r, p = spearmanr(x, y)
    return float(r), float(p)


strength = {}
for g in GUESSERS:
    for c in CONDS:
        p = os.path.join(D, f"guess_{g}_{c}.jsonl")
        if c not in ACTS or not os.path.exists(p):
            continue
        G = load_jsonl(p); pi, wi = META[c]
        lo = np.array([r["lo1"] + r["lo2"] for r in G]); idl = np.array([r["id_lp"] for r in G]); idm = margin(idl, wi)
        for l in [16, 24, 32]:
            for name in ["A", "B", "delta"]:
                m = margin(LP[(c, name, l)], wi)
                r1 = spearmanr(m, lo); r2 = spearmanr(m, idm)
                strength[f"{g}|{c}|L{l}|{name}"] = dict(
                    afc_rho=float(r1[0]), afc_p=float(r1[1]), id_rho=float(r2[0]), id_p=float(r2[1]),
                    afc_within_word=partial_spearman(m, lo, wi), id_within_word=partial_spearman(m, idm, wi),
                    afc_within_word_premise=partial_spearman(m, lo, wi * 100 + pi), mean_margin=float(m.mean()))
S["strength_vs_leak"] = strength
for k, v in strength.items():
    if "|L24|" in k:
        print(k, {a: np.round(b, 3).tolist() for a, b in v.items()})

# across conditions: apply probes trained on the plain secret condition (cross-condition transfer of the direction)
transfer = {}
if "secret" in ACTS:
    A0, B0 = ACTS["secret"]; pi0, wi0 = META["secret"]
    for l in [16, 24, 32]:
        for name in ["A", "delta"]:
            X0 = A0[:, l] if name == "A" else A0[:, l] - B0[:, l]
            for c in ACTS:
                A, B = ACTS[c]; pi, wi = META[c]
                X = A[:, l] if name == "A" else A[:, l] - B[:, l]
                lp = np.zeros((len(wi), 15))
                for f in range(6):
                    fn = fit(X0[(pi0 % 6) != f], wi0[(pi0 % 6) != f])
                    lp[(pi % 6) == f] = fn(X[(pi % 6) == f])
                transfer[f"{c}|L{l}|{name}"] = dict(acc=float((lp.argmax(1) == wi).mean()), margin=float(margin(lp, wi).mean()))
    S["transfer_from_secret_probe"] = transfer
    print({k: round(v["acc"], 2) for k, v in transfer.items() if "L24" in k})

# ---------------------------------------------------------------- 4. logit lens / output probability of the secret word
lens = {}
for c in ACTS:
    n = c.replace("+", "_")
    LA, LB = load(n + "_A", "lens"), load(n + "_B", "lens"); pi, wi = META[c]
    idx = np.arange(len(wi))
    own = lambda L: L[idx, :, wi]                                        # [n, 7]
    oth = lambda L: (L.sum(2) - L[idx, :, wi]) / 14
    dA = own(LA) - own(LB); dO = oth(LA) - oth(LB)                       # effect of the secret prompt on own / other words
    contrast = dA - dO
    # cluster over words for a simple CI
    wmeans = np.stack([contrast[wi == w].mean(0) for w in range(15)])
    lens[c] = dict(layers=LSUB + ["output_logprob"], own_minus_neutral=dA.mean(0).tolist(), other_minus_neutral=dO.mean(0).tolist(),
                   contrast=contrast.mean(0).tolist(), contrast_sem_over_words=(wmeans.std(0, ddof=1) / np.sqrt(15)).tolist(),
                   frac_words_positive=(wmeans > 0).mean(0).tolist(),
                   own_logprob_A=float(own(LA)[:, -1].mean()), own_logprob_B=float(own(LB)[:, -1].mean()))
    print("lens", c, "contrast", np.round(lens[c]["contrast"], 3), "sem", np.round(lens[c]["contrast_sem_over_words"], 3),
          "own lp A/B", round(lens[c]["own_logprob_A"], 2), round(lens[c]["own_logprob_B"], 2))
S["logit_lens"] = lens

fig, ax = plt.subplots(figsize=(5.2, 3.3))
x = np.arange(len(LSUB) + 1)
for c in lens:
    ax.errorbar(x, lens[c]["contrast"], yerr=lens[c]["contrast_sem_over_words"], marker="o", ms=3, capsize=2, label=c.replace("none", "control story"))
ax.axhline(0, color="k", lw=1, ls="--"); ax.set_xticks(x); ax.set_xticklabels([f"L{l}" for l in LSUB] + ["output\nlog-prob"], fontsize=8)
ax.set_ylabel("secret-word token: effect of secret prompt\n(own word minus other 14 words)", fontsize=8); ax.legend(fontsize=7)
plt.tight_layout(); plt.savefig(os.path.join(FIG, "logit_lens.pdf")); plt.close()

json.dump(S, open(os.path.join(RESULTS, "summary_mech.json"), "w"), indent=1)

