                    cells += ["--", "--"]; continue
                cells.append(f"{s['afc_within_word'][0]:+.2f}{star(s['afc_within_word'][1])}")
                cells.append(f"{s['id_within_word'][0]:+.2f}{star(s['id_within_word'][1])}")
